body.script:
const SUPABASE_URL = "https://lvqzkvahfklwzxbxbljv.supabase.co";
const SUPABASE_KEY = "sb_publishable_A122LY08w-r23qZADKtXlA__zPm6E8Q";
const supabaseClient = window.supabase.createClient(SUPABASE_URL, SUPABASE_KEY);

function showTab(tab){
  registerBox.classList.toggle('hidden',tab!=='reg');
  loginBox.classList.toggle('hidden',tab!=='log');
  tabReg.classList.toggle('active',tab==='reg');
  tabLog.classList.toggle('active',tab==='log');
}
function roleFields(){
  driverFields.classList.toggle('hidden',r.value!=='chofer');
  compFields.classList.toggle('hidden',r.value!=='acompanante');
}
function setMsg(el,msg,color='#FCA5A5'){el.textContent=msg;el.style.color=color;}
function previewFile(inputId,imgId){
  const file=document.getElementById(inputId)?.files?.[0];
  if(!file)return;
  const rd=new FileReader();
  rd.onload=()=>{const img=document.getElementById(imgId);img.src=rd.result;img.classList.remove('hidden');};
  rd.readAsDataURL(file);
}
function fileToCompressedBase64(input,maxW=700,quality=.65){
  return new Promise((resolve,reject)=>{
    const file=input?.files?.[0];
    if(!file)return resolve(null);
    const reader=new FileReader();
    const img=new Image();
    reader.onload=e=>img.src=e.target.result;
    img.onload=()=>{
      const scale=Math.min(1,maxW/img.width);
      const canvas=document.createElement('canvas');
      canvas.width=Math.round(img.width*scale);
      canvas.height=Math.round(img.height*scale);
      canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);
      resolve(canvas.toDataURL('image/jpeg',quality));
    };
    reader.onerror=()=>reject(new Error('No se pudo leer la imagen'));
    img.onerror=()=>reject(new Error('Imagen no válida'));
    reader.readAsDataURL(file);
  });
}
async function profile(){
  const s=await supabaseClient.auth.getSession();
  if(!s.data.session)return null;
  const id=s.data.session.user.id;
  const r=await supabaseClient.from("usuarios").select("*").eq("id",id).single();
  return r.data;
}
async function logout(){await supabaseClient.auth.signOut();location.href='login.html';}

async function reg(){
  const btn=document.querySelector('#registerBox .btn.primary');
  try{
    btn.disabled=true;btn.textContent='Creando cuenta...';
    setMsg(m1,'Procesando registro...','#AAB4C0');

    const perfil=await fileToCompressedBase64(f);
    const veh=await fileToCompressedBase64(fveh);
    const licfoto=await fileToCompressedBase64(flic);
    const seg=await fileToCompressedBase64(fseg);
    const doc=await fileToCompressedBase64(fdoc);

    if(!n.value||!t.value||!c.value||!e.value||!p.value||!perfil)throw new Error('Completa datos básicos y foto de perfil.');
    if(p.value.length<6)throw new Error('La contraseña debe tener mínimo 6 caracteres.');
    if(r.value==='chofer'&&(!lic.value||!marca.value||!modelo.value||!placa.value||!veh||!licfoto||!seg||!doc))throw new Error('Chofer debe subir vehículo, licencia, seguro y matrícula/carta de ruta.');

    const authRes=await supabaseClient.auth.signUp({
      email:e.value.trim(),
      password:p.value,
      options:{emailRedirectTo:'https://ttraigo-app.vercel.app/login.html',data:{nombre:n.value,telefono:t.value,cedula:c.value,rol:r.value}}
    });
    if(authRes.error)throw authRes.error;
    const id=authRes.data.user?.id;
    if(!id)throw new Error('Supabase no devolvió ID de usuario.');

    const u=await supabaseClient.from('usuarios').upsert([{id,nombre:n.value,telefono:t.value,email:e.value.trim(),rol:r.value,cedula_id:c.value,foto_base64:perfil,verificado:r.value==='cliente'}],{onConflict:'id'});
    if(u.error)throw new Error('Perfil usuario: '+u.error.message);

    if(r.value==='chofer'){
      const ch=await supabaseClient.from('choferes').insert([{usuario_id:id,nombre:n.value,licencia:lic.value,vehiculo_marca:marca.value,vehiculo_modelo:modelo.value,placa:placa.value,foto_vehiculo:veh,foto_licencia:licfoto,foto_seguro:seg,foto_documento:doc,estado_verificacion:'pendiente'}]);
      if(ch.error)throw new Error('Perfil chofer: '+ch.error.message);
    }

    if(r.value==='acompanante'){
      const ac=await supabaseClient.from('acompanantes').insert([{usuario_id:id,cedula:c.value,experiencia:exp.value,foto_base64:perfil,estado_verificacion:'pendiente'}]);
      if(ac.error)throw new Error('Perfil acompañante: '+ac.error.message);
    }

    setMsg(m1,'Cuenta creada correctamente. Ahora entra con tu correo y contraseña.','#16C47F');
    showTab('log'); le.value=e.value.trim();
  }catch(err){
    console.error(err); setMsg(m1,err.message||'Error creando cuenta.');
  }finally{
    btn.disabled=false;btn.textContent='Crear cuenta segura';
  }
}

async function log(){
  const btn=document.querySelector('#loginBox .btn.primary');
  try{
    btn.disabled=true;btn.textContent='Entrando...';
    setMsg(m2,'Validando acceso...','#AAB4C0');
    const a=await supabaseClient.auth.signInWithPassword({email:le.value.trim(),password:lp.value});
    if(a.error)throw a.error;
    let pr=await profile();
    if(!pr){
      const user=a.data.user;
      await supabaseClient.from('usuarios').upsert([{id:user.id,email:user.email,rol:user.user_metadata?.rol||'cliente',nombre:user.user_metadata?.nombre||'Cliente',telefono:user.user_metadata?.telefono||'',cedula_id:user.user_metadata?.cedula||''}],{onConflict:'id'});
      pr=await profile();
    }
    location.href=pr.rol==='chofer'?'chofer.html':pr.rol==='acompanante'?'acompanante.html':pr.rol==='admin'?'admin.html':'cliente.html';
  }catch(err){
    console.error(err); setMsg(m2,err.message||'No se pudo iniciar sesión.');
  }finally{
    btn.disabled=false;btn.textContent='Entrar';
  }
}
if("serviceWorker" in navigator){window.addEventListener("load",()=>{navigator.serviceWorker.register("/sw.js").catch(()=>{});});}
